 function checkTrace(){const w=work(),paths=[...document.querySelectorAll('#trail-guide path')],points=w.trace.flat().map(p=>[p[0]*100,p[1]*112]);let covered=0,total=0;for(const path of paths){const len=path.getTotalLength();for(let i=0;i<=15;i++){const p=path.getPointAtLength(len*i/15);total++;if(points.some(v=>Math.hypot(v[0]-p.x,v[1]-p.y)<12))covered++;}}const okay=covered/total>=.65;if(okay){const c=traceCase();w.traceDrafts??={};w.traceDrafts[c]=structuredClone(w.trace);rememberSeen(c);w.done=w.seen.includes('upper')&&w.seen.includes('lower');if(c==='upper'&&!w.seen.includes('lower')){w.value='lower';w.trace=structuredClone(w.traceDrafts.lower||[]);}}mark(okay,okay?'Your marks followed the letter trail.':'Start at the coloured dots. Follow more of the trail, then try again. A grown-up can help.');save();render(false);if(okay)play([{key:'move:Well done!'},{key:'text:You followed the letter trail.',text:'You followed the letter trail.'}]);}
