  if(st.type==='blend'){let sliding=false,visited=new Set();const row=scene.querySelector('.blend-trail'),visit=e=>{for(const el of row.children){const b=el.getBoundingClientRect();if(e.clientX>=b.left&&e.clientX<=b.right&&e.clientY>=b.top&&e.clientY<=b.bottom){visited.add(el.dataset.value);el.classList.add('touch-highlight');rememberSeen(el.dataset.value);}}};on(row,'pointerdown',e=>{sliding=true;visited=new Set();row.setPointerCapture(e.pointerId);e.preventDefault();visit(e);});on(row,'pointermove',e=>{if(sliding)visit(e);});on(row,'pointerup',()=>{sliding=false;const all=wordParts(st.word).every((_,i)=>work().seen.includes(String(i)));work().done=all;save();render(false);say(st.word,[...visited].map(i=>({key:'sound:'+wordParts(st.word)[Number(i)],target:'.blend-trail-letter[data-value="'+i+'"]'})).concat(all?[{key:'word:'+st.word,text:st.word}]:[]));});on(row,'pointercancel',()=>{sliding=false;save();});}
